import {computed, shallowRef, toRef} from 'vue'
import {useRouteLocale} from 'vuepress/client'
import {searchIndex} from '@internal/minisearchIndex'

const defaultLocales = {
  '/': {
    placeholder: 'Search',
    resetButtonTitle: 'Reset search',
    backButtonTitle: 'Close search',
    noResultsText: 'No results for',
    searchIndexErrorText: 'Failed to load the search index.',
    noscriptText: 'Search is unavailable without JavaScript.',
    footer: {
      selectText: 'to select',
      selectKeyAriaLabel: 'enter',
      navigateText: 'to navigate',
      navigateUpKeyAriaLabel: 'up arrow',
      navigateDownKeyAriaLabel: 'down arrow',
      closeText: 'to close',
      closeKeyAriaLabel: 'escape',
    },
  },
}

function useLocale(locales) {
  const localesRef = toRef(locales)
  const routeLocale = useRouteLocale()
  return computed(
    () =>
      localesRef.value[routeLocale.value] ??
      defaultLocales[routeLocale.value] ??
      defaultLocales['/'],
  )
}

const searchIndexData = shallowRef(searchIndex)

function useSearchIndex() {
  return searchIndexData
}

function yieldToMainThread() {
  return new Promise((resolve) => setTimeout(resolve))
}

async function loadSearchIndexJSON(locale) {
  const loadIndexModule = searchIndexData.value[locale]
  if (!loadIndexModule) return void 0
  const indexModule = await loadIndexModule()
  if (!indexModule.shards?.length) return indexModule.default
  const serialized = JSON.parse(indexModule.default)
  const shards = await Promise.all(indexModule.shards.map((loadShard) => loadShard()))
  for (const shard of shards) {
    const entries = JSON.parse(shard.default)
    for (const entry of entries) serialized.index.push(entry)
    await yieldToMainThread()
  }
  return JSON.stringify(serialized)
}
if (__VUEPRESS_DEV__ && (import.meta.webpackHot || import.meta.hot))
  __VUE_HMR_RUNTIME__.updateSearchIndex = (data) => {
    searchIndexData.value = data
  }

export {loadSearchIndexJSON, useLocale, useSearchIndex}
